INSERT INTO PrivacyPolicy (Title, Icon, Content, Date)
VALUES (N'1. Общие положения', N'📋',
        N'Настоящая политика обработки персональных данных составлена в соответствии с требованиями Федерального закона от 27.07.2006. №152-ФЗ «О персональных данных» и определяет порядок обработки персональных данных и меры по обеспечению безопасности персональных данных, предпринимаемые магазином «Колесо и поршень» (далее – Оператор).;Оператор ставит своей важнейшей целью и условием осуществления своей деятельности соблюдение прав и свобод человека и гражданина при обработке его персональных данных, в том числе защиты прав на неприкосновенность частной жизни, личную и семейную тайну.;Настоящая политика Оператора в отношении обработки персональных данных (далее – Политика) применяется ко всей информации, которую Оператор может получить о посетителях веб-сайта https://koleso-porshen.ru.;',
        '2026-05-15 13:00:08.2000000'),
       (N'2. Основные понятия', N'📌',
        N'Автоматизированная обработка персональных данных – обработка персональных данных с помощью средств вычислительной техники;Блокирование персональных данных – временное прекращение обработки персональных данных (за исключением случаев, если обработка необходима для уточнения персональных данных);Веб-сайт – совокупность графических и информационных материалов, а также программ для ЭВМ и баз данных, обеспечивающих их доступность в сети интернет по сетевому адресу https://koleso-porshen.ru;Информационная система персональных данных — совокупность содержащихся в базах данных персональных данных, и обеспечивающих их обработку информационных технологий и технических средств;Обезличивание персональных данных — действия, в результате которых невозможно определить без использования дополнительной информации принадлежность персональных данных конкретному Пользователю или иному субъекту персональных данных;Пользователь – любой посетитель веб-сайта https://koleso-porshen.ru.',
        '2026-05-15 13:00:08.2000000'),
       (N'3. Оператор может обрабатывать следующие персональные данные Пользователя', N'📊',
        N'Фамилия, имя, отчество;Номер телефона;Адрес электронной почты;Адрес доставки товара;Также на сайте происходит сбор и обработка обезличенных данных о посетителях (в т.ч. файлов «cookie») с помощью сервисов интернет-статистики (Яндекс Метрика и Гугл Аналитика и других);Вышеперечисленные данные далее по тексту Политики объединены общим понятием Персональные данные;',
        '2026-05-15 13:00:08.2000000'),
       (N'4. Цели обработки персональных данных', N'🎯',
        N'Цель обработки персональных данных Пользователя — информирование Пользователя посредством отправки электронных писем; заключение, исполнение и прекращение гражданско-правовых договоров; предоставление доступа Пользователю к сервисам, информации и/или материалам, содержащимся на веб-сайте.;Также Оператор имеет право направлять Пользователю уведомления о новых продуктах и услугах, специальных предложениях и различных событиях. Пользователь всегда может отказаться от получения информационных сообщений, направив Оператору письмо на адрес электронной почты vm96276915@gmail.com с пометкой «Отказ от уведомлений о новых продуктах и услугах и специальных предложениях».;Обезличенные данные Пользователей, собираемые с помощью сервисов интернет-статистики, служат для сбора информации о действиях Пользователей на сайте, улучшения качества сайта и его содержания.;',
        '2026-05-15 13:00:08.2000000'),
       (N'5. Правовые основания обработки персональных данных', N'⚖️',
        N'Оператор обрабатывает персональные данные Пользователя только в случае их заполнения и/или отправки Пользователем самостоятельно через специальные формы, расположенные на сайте https://koleso-porshen.ru. Заполняя соответствующие формы и/или отправляя свои персональные данные Оператору, Пользователь выражает свое согласие с данной Политикой.;Оператор обрабатывает обезличенные данные о Пользователе в случае, если это разрешено в настройках браузера Пользователя (включено сохранение файлов «cookie» и использование технологии JavaScript);',
        '2026-05-15 13:00:08.2000000'),
       (N'6. Порядок сбора, хранения, передачи и других видов обработки персональных данных', N'🔒',
        N'Безопасность персональных данных, которые обрабатываются Оператором, обеспечивается путем реализации правовых, организационных и технических мер, необходимых для выполнения в полном объеме требований действующего законодательства в области защиты персональных данных.;Оператор обеспечивает сохранность персональных данных и принимает все возможные меры, исключающие доступ к персональным данным неуполномоченных лиц.;Персональные данные Пользователя никогда, ни при каких условиях не будут переданы третьим лицам, за исключением случаев, связанных с исполнением действующего законодательства.;В случае выявления неточностей в персональных данных, Пользователь может актуализировать их самостоятельно, путем направления Оператору уведомление на адрес электронной почты Оператора vm96276915@gmail.com с пометкой «Актуализация персональных данных».;Срок обработки персональных данных является неограниченным. Пользователь может в любой момент отозвать свое согласие на обработку персональных данных, направив Оператору уведомление посредством электронной почты на электронный адрес Оператора vm96276915@gmail.com с пометкой «Отзыв согласия на обработку персональных данных».;',
        '2026-05-15 13:00:08.2000000'),
       (N'7. Трансграничная передача персональных данных', N'🌐',
        N'Оператор до начала осуществления трансграничной передачи персональных данных обязан убедиться в том, что иностранным государством, на территорию которого предполагается осуществлять передачу персональных данных, обеспечивается надежная защита прав субъектов персональных данных.;Трансграничная передача персональных данных на территории иностранных государств, не отвечающих вышеуказанным требованиям, может осуществляться только в случае наличия согласия в письменной форме субъекта персональных данных на трансграничную передачу его персональных данных и/или исполнения договора, стороной которого является субъект персональных данных.;',
        '2026-05-15 13:00:08.2000000'),
       (N'8. Заключительные положения', N'📝',
        N'Пользователь может получить любые разъяснения по интересующим вопросам, касающимся обработки его персональных данных, обратившись к Оператору с помощью электронной почты vm96276915@gmail.com.;"В данном документе будут отражены любые изменения политики обработки персональных данных Оператором. Политика действует бессрочно до замены ее новой версией.;Актуальная версия Политики в свободном доступе расположена в сети Интернет по адресу https://koleso-porshen.ru/privacy_policy.;',
        '2026-05-15 13:00:08.2000000');